def all_token_activations(
    self, texts: list[str], max_tokens: int | None = None
) -> np.ndarray:
    """Per-token residual activations pooled across texts: (total_tokens,
    n_capture, d). BOS positions are excluded — the BOS residual state is
    an extreme-norm outlier that would dominate any PCA."""
    chunks = []
    for _, chunk in self._batches(texts):
        enc = self._encode(chunk, max_tokens=max_tokens)
        mask = enc["attention_mask"].bool()
        mask[:, 0] = False  # drop BOS
        out = self.hf(
            input_ids=enc["input_ids"].to(self.device),
            attention_mask=enc["attention_mask"].to(self.device),
            output_hidden_states=True,
        )
        # (B, T, n_capture, d) -> select real tokens
        h = torch.stack([h.float().cpu() for h in out.hidden_states], dim=2)
        chunks.append(h[mask].numpy())
    return np.concatenate(chunks, axis=0)

